def followup_view(inputs, prior):
    packet=inputs.get('twentyseventh_period_followup')
    if packet is None:return None
    if packet['version']!=1 or packet['content_digest']!=digest({k:v for k,v in packet.items()if k!='content_digest'}):raise ValueError('twentyseventh period packet changed')
    if prior is None or prior['counts']['after']!=150 or packet['prior_digest']!=digest(prior):raise ValueError('twentyseventh period prior changed')
    market=inputs['current_extension']['market_inputs']
    if packet['market_digest']!=digest(market):raise ValueError('twentyseventh period market changed')
    sources={s['announcement_id']:s for s in packet['sources']}
    if len(sources)!=23 or len(packet['sources'])!=23 or set(sources)!=set(SOURCE_BINDINGS):raise ValueError('twentyseventh period source set changed')
    if packet['visual_read']!=VISUAL:raise ValueError('twentyseventh period visual scope changed')
    for aid,s in sources.items():
        if {k:s.get(k)for k in SOURCE_BINDINGS[aid]}!=SOURCE_BINDINGS[aid]or not s['protected_gate_passed']:raise ValueError('twentyseventh period source binding changed')
        if s['published_on']>'2026-11-19':raise ValueError('twentyseventh period future source')
        if set(s['selected_pages'])!={str(n)for n in range(1,s['pages']+1)}or len(s['page_hashes'])!=s['pages']:raise ValueError('twentyseventh period pages missing')
        for n,t in s['selected_pages'].items():
            if sha256(t.encode()).hexdigest()!=s['page_hashes'][int(n)-1]:raise ValueError('twentyseventh period page changed')
    for row in FINANCIAL:
        if D(row['nine_month_yuan'])-D(row['h1_yuan'])!=D(row['quarter_yuan']):raise ValueError('quarter arithmetic changed')
        if row['reported_quarter_yuan'] is not None:
            delta=D(row['quarter_yuan'])-D(row['reported_quarter_yuan'])
            expected=D('.01') if (row['symbol'],row['metric'])==('603959','parent_profit') else D(0)
            if delta!=expected or delta!=D(row['quarter_difference_yuan']):raise ValueError('quarter direct mismatch')
        for aid,n,keys in [(row['h1_source'],row['h1_page'],['h1_yuan']),(row['q3_source'],row['q3_page'],['nine_month_yuan']+(['reported_quarter_yuan']if row['reported_quarter_yuan']is not None else []))]:
            text=sources[aid]['selected_pages'][str(n)].replace(',','').replace(' ','').replace('\n','')
            if any(row[k]not in text for k in keys):raise ValueError('financial source binding changed')
    for r in VISUAL:
        source=sources[r['announcement_id']]
        if source['sha256']!=r['source_sha256'] or source['page_hashes'][r['page']-1]!=r['page_text_sha256'] or not r['verified']:raise ValueError('visual binding changed')
    from st_regime_comparison import build
    windows=event_windows(market,build(market)['daily'],list(sources.values()),allow_nontraded=True,allow_missing=True)
    if digest(windows)!=packet['event_windows_digest']:raise ValueError('twentyseventh period windows changed')
    if packet['quote_reviews']!=QUOTE_REVIEWS:raise ValueError('quote reviews changed')
    review_map={(r['aid'],r['requested_days']):r for r in QUOTE_REVIEWS}
    if len(review_map)!=len(QUOTE_REVIEWS):raise ValueError('duplicate quote review')
    for group in windows:
        for window in group['windows']:
            review=review_map.get((group['aid'],window['requested_days']))
            if window['stock_pct'] is None:
                if review is not None:raise ValueError('nontraded quote review')
                window.update(stock_quote_check='not_calculable',stock_quote_boundary='端点无成交或缺价，收益保留空值。')
                continue
            if review is None or (review['symbol'],review['anchor'],review['through'],review['primary_return_pct'])!=(group['symbol'],window['anchor'],window['through'],window['stock_pct']):raise ValueError('quote window binding changed')
            if D(review['primary_return_pct'])-D(review['cross_return_pct'])!=D(review['difference_pp']):raise ValueError('quote difference changed')
            window.update(stock_quote_check=review['status'],stock_quote_boundary='本窗口端点跨渠道一致。' if review['status']=='matched' else '主源值，跨源待核；复权报价差异未解决，不据此精确比较超额收益。',cross_return_pct=review['cross_return_pct'],cross_difference_pp=review['difference_pp'])
            if review['status']!='matched':
                window.update(primary_stock_pct=window['stock_pct'],stock_pct=None,stock_quote_boundary='报价口径冲突，暂不认证收益；两源异值保留。')
    if packet['cashflow_components']!=CASH_COMPONENTS:raise ValueError('cashflow scope changed')
    for r in CASH_COMPONENTS:
        if not r['visual_verified']:raise ValueError('cashflow visual scope changed')
        for metric,values in r['metrics'].items():
            if D(values['nine_months'])-D(values['H1'])!=D(values['Q3_calculated']):raise ValueError('cashflow arithmetic changed')
            for aid,pages,key in [(r['H1_source'],r['H1_pages'],'H1'),(r['Q3_source'],r['Q3_pages'],'nine_months')]:
                text=''.join(sources[aid]['selected_pages'][str(n)]for n in pages).replace(',','')
                if values[key] not in text:raise ValueError('cashflow source binding changed')
        if D(r['metrics']['operating_inflow']['Q3_calculated'])-D(r['metrics']['operating_outflow']['Q3_calculated'])!=D(r['Q3_net']):raise ValueError('cashflow net changed')
    if packet['focused_comparisons']!=FOCUSED or packet['index_review']!=INDEX_REVIEW:raise ValueError('comparison proof changed')
    daily={r['date']:D(str(r['return_pct']))for r in build(market)['daily']if '2026-07-03'<r['date']<='2026-11-19'}
    calendar=['2026-07-03',*sorted(daily)]
    prices={(r['symbol'],r['trade_date']):r for r in market['fixed_prices']}
    indices={r['trade_date']:D(str(r['close']))for r in market['benchmarks']if r['benchmark_id']=='csi_all_share'}
    window_map={r['aid']:r for r in windows}
    for r in FOCUSED['rows']:
        base=window_map[r['aid']]['windows'][0]['anchor'];pos=calendar.index(base);start=calendar[max(0,pos-5)]
        before=r['before_5_sessions'];days=calendar[max(0,pos-5)+1:pos+1]
        if (before['anchor'],before['through'],before['observed_days'])!=(start,base,len(days)):raise ValueError('pre-event calendar changed')
        a,z=(prices[(r['symbol'],d)]for d in [start,base])
        if not a['has_trade']or not z['has_trade']:raise ValueError('pre-event endpoint missing')
        st=D(1)
        for d in days:st*=1+daily[d]/100
        expected=[(D(str(z['close']))/D(str(a['close']))-1)*100,(st-1)*100,(indices[base]/indices[start]-1)*100]
        if [D(before[k])for k in ['stock_pct','st_pct','market_pct']]!=expected:raise ValueError('pre-event return changed')
        if r['after']!=[{k:v for k,v in w.items()if k not in ['stock_quote_check','stock_quote_boundary','cross_return_pct','cross_difference_pp']}for w in window_map[r['aid']]['windows']]:raise ValueError('focused post-event windows changed')
    from decimal import ROUND_HALF_UP
    expected_dates={d for g in windows for w in g['windows']for d in [w['anchor'],w['through']]}
    if {r['date']for r in INDEX_REVIEW['rows']}!=expected_dates or INDEX_REVIEW['conflicts']!=0:raise ValueError('index review scope changed')
    for r in INDEX_REVIEW['rows']:
        if indices[r['date']]!=D(r['provider'])or indices[r['date']].quantize(D('.01'),rounding=ROUND_HALF_UP)!=D(r['official'])or D(r['provider'])-D(r['official'])!=D(r['raw_difference']):raise ValueError('official index precision changed')
    result={'through': '2026-11-19', 'title': '赠与、判决和过户推进后，风险与行情各自怎样变化？', 'answer': '百利已有部分捐赠收款披露，但经营仍亏；金鸿顺利润增长包含减值转回，一审尚未生效；葫芦娃现金正流入与亏损并存；帅电过户与付款推进，后续经营贡献仍待验证。先比较发生了什么，再看个股与ST、大盘的同窗差异。', 'counts': {'files': 23, 'new_files': 23, 'reused_files': 0, 'pages': 881, 'new_pages': 881, 'viewed_pages': 22, 'initial_coverage': 150, 'complete_windows': 60, 'unfinished_windows': 9, 'stock_endpoint_gaps': 0}, 'boundary': '228条期间目录；23份881页实际核22页，不认证全文。69窗口60满9未满，69股票收益跨源端点一致；大盘48端点在官方精度一致，ST仅复算既有序列。15财务衔接中12项有直接单季、其中1项差0.01元；另4项现金仅葫芦娃有直接单季，其余3项差额推算。百利更正半年扣非缺直接值，未造桥接。重复窗口不是独立经验，未识别公告净因果；原名单、退出与历史报价债务继续保留。', 'method_promotions': 0}
    result.update(chains=CHAINS,financial_bridge=FINANCIAL,cashflow_components=CASH_COMPONENTS,phase_comparisons=[],focused_comparisons=FOCUSED,index_review=INDEX_REVIEW,event_windows=windows,sources=[{k:v for k,v in s.items()if k not in ["raw_item","selected_pages","page_hashes"]}for s in sources.values()])
    return result
